package com.autocare.platform.order;

import com.autocare.platform.file.*;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.*;
import java.util.concurrent.*;
import javax.imageio.ImageIO;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcPublicImagesTest extends JdbcExperienceDetailTest {
 PublicImages images;OperatorActor reviewer;String reference;byte[] copy;long archive;
 @BeforeEach void imageSetup(TestInfo info)throws Exception{
  jdbc.execute("DROP TRIGGER IF EXISTS reject_public_image_audit");jdbc.update("DELETE FROM public_image_event");jdbc.update("DELETE FROM public_image_application");
  if(info.getTestMethod().orElseThrow().getDeclaringClass()!=JdbcPublicImagesTest.class)return;
  reference=approved();reviewer=operator();
  var out=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(3,2,BufferedImage.TYPE_INT_RGB),"png",out);copy=out.toByteArray();
  jdbc.update("INSERT INTO file_object(id,owner_type,owner_id,object_key,content_type,size_bytes,scan_status) VALUES(801,'user',1,?,'image/png',?,'CLEAN'),(802,'user',1,?,'image/png',?,'CLEAN')","uploads/"+key(),copy.length,"uploads/"+key(),copy.length);
  jdbc.update("INSERT INTO vehicle_archive(id,vehicle_id,archive_type,content,input_type) VALUES(800,1,2,'{}',3)");archive=800;
  jdbc.update("INSERT INTO vehicle_archive_file(archive_id,file_id,position) VALUES(800,801,0)");
  SignedObjectStore store=new SignedObjectStore(){public boolean isPrivate(){return true;}public void put(String k,String t,byte[] b){}public void delete(String k){}public StoredObject stat(String k){return new StoredObject("image/png",copy.length);}public String signGet(String k,int s){throw new AssertionError("Public copies must never sign originals");}public byte[] read(String k,int n){return copy.clone();}};
  images=new PublicImages(db,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())),service,store,true);
 }
 @AfterEach void imageCleanup(){jdbc.execute("DROP TRIGGER IF EXISTS reject_public_image_audit");}
 ObjectNode selection(){return db.mapper.createObjectNode().put("experience_id",reference).put("archive_id",archive).put("source_file_id",801).put("copy_file_id",802);}
 ObjectNode consentImage(){var b=selection();return b.put("preview_hash",images.preview(owner,b).get("preview_hash").toString()).put("consent_version",PublicImages.CONSENT).put("consent",true);}
 long applyImage(){return images.submit(owner,key(),consentImage()).path("data").path("application_id").asLong();}
 ObjectNode reviewImage(long revision,String decision){return db.mapper.createObjectNode().put("expected_revision",revision).put("decision",decision).putNull("reason_code");}
 String approveImage(long id){images.moderate(reviewer,id,key(),reviewImage(1,"APPROVE"));return jdbc.queryForObject("SELECT public_id FROM public_image_application WHERE id=?",String.class,id);}
 @Test void separatelyConsentedCopyAndPublicProjectionNeverExposePrivateIdsOrUrls(){var b=selection();var preview=images.preview(owner,b);assertEquals(3,preview.get("width"));assertFalse(preview.containsKey("object_key"));long id=applyImage();String uuid=approveImage(id);assertArrayEquals(copy,images.bytes(other,2,uuid));var result=db.mapper.valueToTree(images.list(other,2,reference));assertEquals(Set.of("public_id","width","height","published_at"),db.mapper.convertValue(result.path("items").get(0),Map.class).keySet());assertFalse(result.toString().contains("source_file_id"));assertFalse(result.toString().contains("owner_id"));}
 @Test void rejectsOriginalAsCopyAndOtherOwnerFiles(){var b=selection().put("copy_file_id",801);assertEquals(400,status(()->PublicImages.input(b.toString(),"preview")));assertEquals(404,status(()->images.preview(other,selection())));jdbc.update("UPDATE file_object SET owner_id=2 WHERE id=802");assertEquals(404,status(()->images.preview(owner,selection())));}
 @Test void changedCopyOrSourceCannotReuseOldPreview()throws Exception{var b=consentImage();byte[] old=copy;var changed=new BufferedImage(3,2,BufferedImage.TYPE_INT_RGB);changed.setRGB(1,1,0xff123456);var out=new ByteArrayOutputStream();ImageIO.write(changed,"png",out);copy=out.toByteArray();jdbc.update("UPDATE file_object SET size_bytes=? WHERE id=802",copy.length);assertEquals(409,status(()->images.submit(owner,key(),b)));copy=old;jdbc.update("UPDATE file_object SET size_bytes=? WHERE id=802",copy.length);var originalConsent=consentImage();jdbc.update("UPDATE vehicle_archive SET content=JSON_OBJECT('changed',true) WHERE id=800");assertEquals(409,status(()->images.submit(owner,key(),originalConsent)));}
 @Test void inactiveScanParentWithdrawalAndVehicleTransferHideImageImmediately(){long id=applyImage();String uuid=approveImage(id);jdbc.update("UPDATE file_object SET scan_status='INFECTED',updated_at=DATE_ADD(updated_at,INTERVAL 1 SECOND) WHERE id=801");assertEquals(404,status(()->images.bytes(other,2,uuid)));jdbc.update("UPDATE file_object SET scan_status='CLEAN',updated_at=DATE_ADD(updated_at,INTERVAL 1 SECOND) WHERE id=801");assertEquals(404,status(()->images.bytes(other,2,uuid)),"changed source must require fresh consent");images.withdraw(owner,id,key(),db.mapper.createObjectNode().put("expected_revision",2));long next=applyImage();String current=approveImage(next);assertNotEquals(uuid,current);assertArrayEquals(copy,images.bytes(other,2,current));cards().change(owner,cardId,key(),db.mapper.createObjectNode(),false);assertEquals(404,status(()->images.bytes(other,2,current)));images.withdraw(owner,next,key(),db.mapper.createObjectNode().put("expected_revision",2));}
 @Test void explicitWithdrawalNeverRevivesOriginalPublicUuid(){long id=applyImage();String uuid=approveImage(id);images.withdraw(owner,id,key(),db.mapper.createObjectNode().put("expected_revision",2));assertEquals(404,status(()->images.bytes(other,2,uuid)));assertEquals(409,status(()->images.moderate(reviewer,id,key(),reviewImage(1,"APPROVE"))));long next=applyImage();String nextUuid=approveImage(next);assertNotEquals(uuid,nextUuid);assertEquals(404,status(()->images.bytes(other,2,uuid)));}
 @Test void permanentCreateRecoverySurvivesSourceFailureAndRejectsNewBody(){var b=consentImage();String request=key();var result=images.submit(owner,request,b);jdbc.update("DELETE FROM idempotency_record");jdbc.update("UPDATE file_object SET is_deleted=1 WHERE id=802");assertEquals(result.path("data"),images.submit(owner,request,b).path("data"));assertEquals(400,status(()->images.submit(owner,request,b.deepCopy().put("preview_hash","b".repeat(64)))));}
 @Test void reviewerGetsOnlyConsentedCopyAndCannotReadOriginalPrivateArchive(){long id=applyImage();assertArrayEquals(copy,images.reviewPreview(reviewer,id));assertEquals(404,status(()->images.ownerPreview(other,id)));jdbc.update("UPDATE operator_account SET can_review=0 WHERE id=?",reviewer.id());assertEquals(403,status(()->images.reviewPreview(reviewer,id)));}
 @Test void auditFailureRollsBackApprovalAndCanRetrySameRequest(){long id=applyImage();String request=key();jdbc.execute("CREATE TRIGGER reject_public_image_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,status(()->images.moderate(reviewer,id,request,reviewImage(1,"APPROVE"))));assertEquals("PENDING",jdbc.queryForObject("SELECT status FROM public_image_application WHERE id=?",String.class,id));jdbc.execute("DROP TRIGGER reject_public_image_audit");images.moderate(reviewer,id,request,reviewImage(1,"APPROVE"));assertEquals("APPROVED",jdbc.queryForObject("SELECT status FROM public_image_application WHERE id=?",String.class,id));}
 @Test void tamperedModelOrPngCannotEscapeTrustedScope(){long id=applyImage();String uuid=approveImage(id);jdbc.update("UPDATE vehicle SET model_id=2 WHERE id=2");jdbc.update("UPDATE public_image_application SET model_id=2 WHERE id=?",id);assertEquals(404,status(()->images.bytes(other,2,uuid)));jdbc.update("UPDATE vehicle SET model_id=1 WHERE id=2");jdbc.update("UPDATE public_image_application SET model_id=1 WHERE id=?",id);assertArrayEquals(copy,images.bytes(other,2,uuid));jdbc.update("UPDATE public_image_application SET png=? WHERE id=?",new byte[]{1,2,3},id);assertEquals(404,status(()->images.bytes(other,2,uuid)));assertEquals(404,status(()->images.ownerPreview(owner,id)));}
 @Test void approveAndWithdrawSerializeOnOneRevision()throws Exception{long id=applyImage();var pool=Executors.newFixedThreadPool(2);try{var gate=new CountDownLatch(1);var x=pool.submit(()->{gate.await();try{images.moderate(reviewer,id,key(),reviewImage(1,"APPROVE"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var y=pool.submit(()->{gate.await();try{images.withdraw(owner,id,key(),db.mapper.createObjectNode().put("expected_revision",1));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});gate.countDown();var statuses=new ArrayList<>(List.of(x.get(30,TimeUnit.SECONDS),y.get(30,TimeUnit.SECONDS)));Collections.sort(statuses);assertEquals(List.of(200,409),statuses);}finally{pool.shutdownNow();}}
}
